# Synchronize dated outcomes, including the three owner-deferred open targets.
require_relative 'contracts'
require 'yaml'
mode=ARGV.fetch(0,'check')
abort 'Usage: ruby verification/existence/sync.rb [refresh|check]' unless %w[refresh check].include?(mode)
index=AtlasContracts::Index.new
Dir.chdir(index.root)
begin
  result=index.validate!;rows=result.fetch(:entries)
  page=<<~MD
    # Comparator results — 25 October 2026

    <!-- Generated by verification/existence/sync.rb from reviewed contracts and original receipts. -->
    **42 of 45 targets passed; three remain open at the owner's request.**
    Albert-model F₄ and the aggregate isomorphism/nonisomorphism pair stopped at
    the 9 GiB owned-memory cap. No retry or pass is implied.

    The 39 model-existence targets cover all 33 completed catalogue entries and
    six additional realizations. All four strengthened discriminator targets
    passed. The 43 existence/discriminator references import only mathlib; the
    two aggregate references share concrete carriers and normalization definitions.

    Basic existence contracts have no separate noncommutativity conjunct.
    Internal Lean theorems and the reviewed strengthened specifications are retained.
    [Original receipts and exact inputs](2026-10-25-draft/README.md) remain unchanged.
    These are dated local-snapshot results. [Frozen-release acceptance](../MAINTENANCE.md)
    is evaluated separately and remains pending.

    | Target | Result | Exact specification and evidence |
    |---|---|---|
  MD
  rows.each do |r|
    p=r.fetch('evidence').delete_prefix('verification/existence/')
    outcome=r['recorded_status']=='passed' ? 'Passed (dated scope)' : 'Open — memory stop; deferred'
    page<<"| `#{r['declaration']}` | #{outcome} | [reference](#{p}/#{r['reference_file']}), [solution](#{p}/#{r['solution_file']}), [receipt](#{p}/RESULT.json) |\n"
  end
  targets=rows.map { |r|r.slice('declaration','scope','catalogue_id','primary_catalogue_contract','realization','recorded_status','current_export_acceptance') }
  yaml=YAML.safe_load(File.read('formalization.yaml'));expected=Marshal.load(Marshal.dump(yaml))
  expected.fetch('status')['main_results']=rows.map do |r|
    p=r.fetch('evidence')
    {'name'=>r['declaration'],'declaration'=>r['declaration'],'file'=>p+'/'+r['solution_file'],
      'comparator_config'=>p+'/'+r['configuration'],'result_record'=>p+'/RESULT.json',
      'verification_status'=>r['recorded_status'],'evidence_scope'=>'dated local snapshot; exact-export acceptance separate',
      'deferred'=>result[:open].include?(r['declaration']),'sorry_count'=>0}
  end
  expected.fetch('verification')['reports']=[{'kind'=>'Comparator','file'=>'verification/existence/RESULTS.md','passed'=>42,'total'=>45,'open'=>3},
    {'kind'=>'Nanoda','file'=>'verification/nanoda/2026-10-24-draft/KERNEL_RESULT.json','status'=>'passed-kernel-check-with-pretty-printer-warning','checked_declarations'=>139617}]
  generated={'verification/existence/RESULTS.md'=>page,'verification/existence/targets.json'=>JSON.pretty_generate(targets)+"\n",'formalization.yaml'=>YAML.dump(expected)}
  generated.each do |p,s|
    if mode=='refresh'
      File.write(p,s) unless File.file?(p) && File.binread(p)==s.b
    else
      raise "Stale generated metadata #{p}" unless File.file?(p) && File.binread(p)==s.b
    end
  end
  puts "PASS: 45 reviewed contracts, all 33 catalogue defaults covered; 42 dated passes and 3 explicitly open targets (#{mode}). No proof replay or new verification acceptance."
rescue=>e
  warn "Contract metadata refused: #{e.message}"
  exit 1
end
